import unittest


def strange_sort_list(lst):

    res, switch = [], True
    while lst:
        res.append(min(lst) if switch else max(lst))
        lst.remove(res[-1])
        switch = not switch
    return res


class TestStrangeSortList(unittest.TestCase):

    def test_basic_mixed_list(self):
        self.assertEqual(strange_sort_list([1, 2, 3, 4]), [1, 4, 2, 3])

    def test_all_equal_elements(self):
        self.assertEqual(strange_sort_list([5, 5, 5, 5]), [5, 5, 5, 5])

    def test_empty_list(self):
        self.assertEqual(strange_sort_list([]), [])

    def test_single_element(self):
        self.assertEqual(strange_sort_list([42]), [42])

    def test_negative_numbers(self):
        self.assertEqual(strange_sort_list([1, -1, 2, -2, 3, -3]),
                         [-3, 3, -2, 2, -1, 1])

    def test_two_elements(self):
        self.assertEqual(strange_sort_list([10, 2]), [2, 10])

    def test_duplicates(self):
        self.assertEqual(strange_sort_list([3, 1, 3, 1, 2]), [1, 3, 1, 3, 2])

    def test_already_alternating(self):
        self.assertEqual(strange_sort_list([1, 4, 2, 3]), [1, 4, 2, 3])

    def test_unsorted_input(self):
        self.assertEqual(strange_sort_list([9, 1, 5, 3, 7]), [1, 9, 3, 7, 5])

    def test_result_length_matches(self):
        original = [4, 8, 15, 16, 23, 42]
        result = strange_sort_list(original[:])
        self.assertEqual(len(result), len(original))


if __name__ == "__main__":
    unittest.main()
